-- Silver-tier surveys ($1–$2 reward), 25 questions each (subset of full 233-survey seed).
-- Reflective mix (shortened from Gold/Platinum templates). Idempotent on slug.
--
-- Requires public.surveys, payment_categories (silver), survey_category / payment_category_id columns.
-- Safe to run parts in order or separately; re-runs skip existing slugs (ON CONFLICT DO NOTHING).

-- Part 1 of 4 — 58 surveys (global rows 1–58 of 233).

insert into public.surveys (slug, title, description, reward_cents, estimated_minutes, questions, is_active, survey_category, payment_category_id)
select
  'silver-tech-001',
  'AI at work',
  'How assistants and automation change drafting, checking, and who owns the outcome.',
  100,
  16,
  $json$[{"id": "silvertech001_01", "type": "choice", "label": "When you think about this topic in your own life, how often does it feel emotionally ‘loaded’ rather than neutral?", "options": ["Almost always", "Often", "Sometimes", "Rarely", "Almost never"]}, {"id": "silvertech001_02", "type": "choice", "label": "How much do your answers here depend on your current life stage (care, dependents, income, health)?", "options": ["A great deal", "Quite a bit", "Somewhat", "A little", "Hardly at all"]}, {"id": "silvertech001_03", "type": "choice", "label": "Do you usually seek out disagreement on this topic, or prefer communities that largely agree with you?", "options": ["Seek disagreement", "Mix of both", "Prefer agreement", "Avoid the topic", "Not sure"]}, {"id": "silvertech001_04", "type": "choice", "label": "Which best describes your relationship to ‘expert’ voices on this topic?", "options": ["I defer to them", "I weigh them against experience", "I’m skeptical by default", "I ignore them", "It varies wildly"]}, {"id": "silvertech001_05", "type": "choice", "label": "If you had to choose, is this topic more about individual choices or systems and institutions?", "options": ["Mostly individual", "Lean individual", "Even split", "Lean systems", "Mostly systems"]}, {"id": "silvertech001_06", "type": "choice", "label": "How comfortable are you admitting uncertainty or changing your mind publicly about this?", "options": ["Very comfortable", "Somewhat", "Neutral", "Uncomfortable", "I avoid it"]}, {"id": "silvertech001_07", "type": "text", "label": "Describe a recent moment when this topic forced you to choose between two values you both care about. What did you pick, and what did it cost?"}, {"id": "silvertech001_08", "type": "text", "label": "What is one widely repeated opinion about this topic that you think is too simple? What nuance is usually missing?"}, {"id": "silvertech001_09", "type": "text", "label": "If someone you respect disagreed with you on this, what is the strongest version of their argument you could offer on their behalf?"}, {"id": "silvertech001_10", "type": "choice", "label": "You can improve one thing in this domain with serious effort, or help three people in a smaller way. Which pulls you?", "options": ["The deep single improvement", "The broader smaller help", "I’d try to combine", "Refuse the frame", "Depends on who is affected"]}, {"id": "silvertech001_11", "type": "choice", "label": "A policy change would help many strangers but slightly inconvenience you weekly. Support it?", "options": ["Yes, strongly", "Yes, cautiously", "Need more detail", "Probably not", "No"]}, {"id": "silvertech001_12", "type": "choice", "label": "You discover a habit of yours has unintended harm you didn’t see before. What’s your first instinct?", "options": ["Change quickly", "Research more", "Feel guilty", "Rationalize", "Talk to someone"]}, {"id": "silvertech001_13", "type": "choice", "label": "How much do you weigh future people (you’ll never meet) in decisions that affect this topic today?", "options": ["A lot", "Some", "Unsure how to", "Rarely", "Not consciously"]}, {"id": "silvertech001_14", "type": "choice", "label": "When brands or leaders speak on this topic, what erodes your trust fastest?", "options": ["Vague virtue signaling", "Data overreach", "Hypocrisy", "Fear messaging", "Overpromising"]}, {"id": "silvertech001_15", "type": "choice", "label": "If you could only protect one—honesty, kindness, or effectiveness—which do you lean on when they conflict here?", "options": ["Honesty", "Kindness", "Effectiveness", "Refuse to rank", "Situational blend"]}, {"id": "silvertech001_16", "type": "choice", "label": "Do you experience this topic more as a private inner struggle or a public political fight?", "options": ["Mostly private", "More private", "Both equally", "More public", "Mostly public"]}, {"id": "silvertech001_17", "type": "text", "label": "Name one assumption people make about ‘people like you’ in this topic that is often wrong or incomplete."}, {"id": "silvertech001_18", "type": "text", "label": "What is a constructive disagreement you wish more people could have about this—without collapsing into teams?"}, {"id": "silvertech001_19", "type": "choice", "label": "After reflecting, how clear is your own position on this topic?", "options": ["Very clear", "Somewhat clear", "Mixed", "Uncertain", "Intentionally open"]}, {"id": "silvertech001_20", "type": "choice", "label": "Would you want a close friend to challenge you on this more often, less often, or about the same?", "options": ["More often", "About the same", "Less often", "Depends on how they do it", "Not sure"]}, {"id": "silvertech001_21", "type": "choice", "label": "How likely are you to seek new information on this in the next month?", "options": ["Very likely", "Likely", "Maybe", "Unlikely", "Very unlikely"]}, {"id": "silvertech001_22", "type": "choice", "label": "Do you feel more hopeful, more concerned, or about the same compared to a year ago?", "options": ["More hopeful", "About the same", "More concerned", "Both hopeful and concerned", "I avoid comparing"]}, {"id": "silvertech001_23", "type": "choice", "label": "If you could fund one type of project in this area, what would you pick?", "options": ["Education", "Infrastructure", "Research", "Direct aid", "Advocacy"]}, {"id": "silvertech001_24", "type": "choice", "label": "How much does community (online or offline) matter for how you think about this topic?", "options": ["Essential", "Important", "Moderate", "Minor", "I think alone"]}, {"id": "silvertech001_25", "type": "choice", "label": "Final calibration: how representative do you think your answers are of people in situations very different from yours?", "options": ["Very representative", "Somewhat", "Not very", "I doubt it", "I actively don’t know"]}]$json$::jsonb,
  true,
  'Technology',
  pc.id
from public.payment_categories pc
where pc.slug = 'silver'
limit 1
on conflict (slug) do nothing;

